                raise ValueError(
                    "Could not coarsen a dimension of size {} with "
                    "window {}".format(size, window)
                )
        elif boundary[d] == "trim":
            if side[d] == "left":
                variable = variable.isel({d: slice(0, window * n)})
            else:
                excess = size - window * n
                variable = variable.isel({d: slice(excess, None)})

